const links = Object.entries({"ms-font-400": "https://testingcf.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.3.1/400.css", "ms-font-600": "https://testingcf.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.3.1/600.css", "ms-font-700": "https://testingcf.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.3.1/700.css"}).map(([id, href]) => {
  let link = doc.getElementById(id);
  if (!link) {
    link = doc.createElement("link");
    link.id = id;
    link.rel = "stylesheet";
    link.href = href;
    doc.head.appendChild(link);
  }
  return link;
});
const pick = (e) => {
  const opt = e.target.closest(".custom-ms-opt");
  if (!opt) return;
  opt.parentElement.querySelectorAll(".custom-ms-opt").forEach((x) => x.classList.toggle("custom-on", x === opt));
  const box = doc.getElementById("send_textarea");
  box.value = opt.textContent.trim();
  box.dispatchEvent(new Event("input", { bubbles: true }));
  box.focus();
};
doc.addEventListener("click", pick);
window.addEventListener("pagehide", () => {
  style.remove();
  links.forEach((link) => link.remove());
  doc.removeEventListener("click", pick);
});
